function subscribeCoinPackages(onUpdate) {
	const collRef = collection(db, "coin_packages");
	return onSnapshot(collRef, (snap) => {
		if (!snap.empty) {
			const pkgs = snap.docs.map((d) => ({
				id: d.id,
				...d.data()
			}));
			if (pkgs.some((p) => p.id === "pack_1000" && p.coins === 1e3 && p.pricePkr === 2e3)) {
				onUpdate(DEFAULT_COIN_PACKAGES);
				return;
			}
			pkgs.sort((a, b) => a.coins - b.coins);
			onUpdate(pkgs);
		} else {
			if (isVerifiedAdminSession()) DEFAULT_COIN_PACKAGES.forEach((pkg) => {
				setDoc(doc(db, "coin_packages", pkg.id), pkg, { merge: true }).catch(console.warn);
			});
			onUpdate(DEFAULT_COIN_PACKAGES);
		}
	}, () => {
		onUpdate(DEFAULT_COIN_PACKAGES);
	});
}
