	const normalizedUsername = rawUsername ? rawUsername.startsWith("@") ? rawUsername : `@${rawUsername}` : `@${(rawEmail.split("@")[0] || "user").replace(/[^a-zA-Z0-9_]/g, "").toLowerCase()}`;
