/**
* Lenzo Party Live - Coin System & Reference Pricing Configuration
* Proposed reference pricing: 1 coin ≈ PKR 2
*/
var COIN_CONFIG = {
	COIN_TO_PKR_RATE: 2,
	CURRENCY_NAME: "Lenzo Coins",
	COIN_ICON: "🪙",
	coinsToPkr: (coins) => {
		return Math.round(coins * COIN_CONFIG.COIN_TO_PKR_RATE);
	},
	formatCoinsWithPkr: (coins, compact = false) => {
		return `${compact ? formatCompactNumber(coins) : coins.toLocaleString()} Coins (≈ PKR ${COIN_CONFIG.coinsToPkr(coins).toLocaleString()})`;
	},
	formatPkrEquivalent: (coins) => {
		return `≈ PKR ${COIN_CONFIG.coinsToPkr(coins).toLocaleString()}`;
	},
	formatCoins: (coins) => {
		return `${COIN_CONFIG.COIN_ICON} ${coins.toLocaleString()}`;
	}
};
function formatCompactNumber(num) {
	if (num >= 1e6) return (num / 1e6).toFixed(1) + "M";
	if (num >= 1e3) return (num / 1e3).toFixed(1) + "K";
	return num.toString();
}
