		if (m.commentsCount > 0) parts.push(`💬 ${m.commentsCount}`);
		if (m.likesCount > 0) parts.push(`❤️ ${formatCompact(m.likesCount)}`);
		if (m.watchMinutes > 0) parts.push(`⏱ ${m.watchMinutes}m`);
