var RoomService = class {
	async fetchRoomSeats(roomId, maxSeats = 8) {
		try {
			const res = await apiFetch(`/api/rooms/${encodeURIComponent(roomId)}/seats`);
			if (res.ok && res.headers.get("content-type")?.includes("application/json")) return await res.json();
		} catch (e) {
			console.warn("Failed to fetch room seats from backend:", e);
		}
		return {
			seats: Array(maxSeats).fill(null),
			pendingRequests: [],
			mutedSeatIndices: []
		};
	}
	async requestSeat(roomId, user, requestedSeatIndex, roomHostId, roomMeta) {
		const res = await apiFetch(`/api/rooms/${encodeURIComponent(roomId)}/request_seat`, {
			method: "POST",
			body: JSON.stringify({
				user,
				requestedSeatIndex,
				roomHostId,
				roomMeta
			})
		});
		if (!res.ok) {
			const err = await res.json().catch(() => ({ error: "Failed to request seat" }));
			throw new Error(err.error || "Failed to request seat");
		}
		return (await res.json()).request;
	}
	async cancelSeatRequest(roomId, userId) {
		await apiFetch(`/api/rooms/${encodeURIComponent(roomId)}/cancel_seat_request`, {
			method: "POST",
			body: JSON.stringify({ userId })
		});
	}
	async respondSeatRequest(roomId, hostId, applicantId, approve, targetSeatIndex, applicantUser) {
		const res = await apiFetch(`/api/rooms/${encodeURIComponent(roomId)}/respond_seat_request`, {
			method: "POST",
			body: JSON.stringify({
				hostId,
				applicantId,
				approve,
				targetSeatIndex,
				applicantUser
			})
		});
		if (!res.ok) {
			const err = await res.json().catch(() => ({ error: "Action failed" }));
			throw new Error(err.error || "Host response failed");
		}
		return await res.json();
	}
	async removeSeat(roomId, hostId, seatIndex, roomMeta, targetUserId) {
		const res = await apiFetch(`/api/rooms/${encodeURIComponent(roomId)}/remove_seat`, {
			method: "POST",
			body: JSON.stringify({
				hostId,
				seatIndex,
				targetUserId,
				roomMeta
			})
		});
		if (!res.ok) {
			const err = await res.json().catch(() => ({ error: "Action failed" }));
			throw new Error(err.error || "Failed to kick user from seat");
		}
		return await res.json();
	}
	async leaveSeat(roomId, userId, roomHostId, roomMeta) {
		const res = await apiFetch(`/api/rooms/${encodeURIComponent(roomId)}/leave_seat`, {
			method: "POST",
			body: JSON.stringify({
				userId,
				roomHostId,
				roomMeta
			})
		});
		if (!res.ok) {
			const err = await res.json().catch(() => ({ error: "Action failed" }));
			throw new Error(err.error || "Failed to leave seat");
		}
		return await res.json();
	}
	async muteSeat(roomId, actorId, seatIndex, isMuted) {
		const res = await apiFetch(`/api/rooms/${encodeURIComponent(roomId)}/mute_seat`, {
			method: "POST",
			body: JSON.stringify({
				actorId,
				seatIndex,
				isMuted
			})
		});
		if (!res.ok) {
			const err = await res.json().catch(() => ({ error: "Action failed" }));
			throw new Error(err.error || "Failed to update mic state");
		}
		return await res.json();
	}
	async updateRoomSettings(roomId, hostId, updates) {
		const res = await apiFetch(`/api/rooms/${encodeURIComponent(roomId)}/settings`, {
			method: "POST",
			body: JSON.stringify({
				hostId,
				...updates
			})
		});
		if (!res.ok) {
			const err = await res.json().catch(() => ({ error: "Failed to update room settings" }));
			throw new Error(err.error || "Failed to update room settings");
		}
	}
};
